// Calcola quanto pesa ogni asse (X, Y, Z) in base alla normale
vec3 blend = abs(n_model);
blend /= max(blend.x + blend.y + blend.z, 0.00001);

// Genera pattern procedurali diversi per ogni piano di proiezione
vec3 colX = vec3(sin(pModel.y * 30.0) * 0.5 + 0.5, 0.0, 0.0); // Strisce rosse sul piano YZ
vec3 colY = vec3(0.0, sin(pModel.x * 30.0) * 0.5 + 0.5, 0.0); // Strisce verdi sul piano XZ
vec3 colZ = vec3(0.0, 0.0, sin(pModel.x * 30.0) * 0.5 + 0.5); // Strisce blu sul piano XY

// Miscela i pattern usando i pesi della normale
textureCol = colX * blend.x + colY * blend.y + colZ * blend.z;
